PRAGMA foreign_keys=ON;
CREATE TABLE users(email TEXT PRIMARY KEY COLLATE NOCASE, role TEXT NOT NULL CHECK(role IN('admin','volunteer','reviewer')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), trained INTEGER NOT NULL DEFAULT 0 CHECK(trained IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE campaigns(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','closed')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE memberships(campaign_id TEXT NOT NULL REFERENCES campaigns(id), email TEXT NOT NULL REFERENCES users(email), PRIMARY KEY(campaign_id,email));
CREATE TABLE scenarios(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),title TEXT NOT NULL,instructions TEXT NOT NULL);
CREATE TABLE tasks(id TEXT PRIMARY KEY,scenario_id TEXT NOT NULL REFERENCES scenarios(id),title TEXT NOT NULL,instructions TEXT NOT NULL);
CREATE TABLE models(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),label TEXT NOT NULL,provider TEXT NOT NULL CHECK(provider IN('openai','anthropic')),model_name TEXT NOT NULL,system_prompt TEXT NOT NULL DEFAULT '',max_tokens INTEGER NOT NULL DEFAULT 512 CHECK(max_tokens BETWEEN 64 AND 2048),enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE conversations(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),scenario_id TEXT NOT NULL REFERENCES scenarios(id),model_id TEXT NOT NULL REFERENCES models(id),owner TEXT NOT NULL REFERENCES users(email),model_snapshot TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'open' CHECK(state IN('open','submitted')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE turns(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),seq INTEGER NOT NULL,prompt TEXT NOT NULL,response TEXT NOT NULL DEFAULT '',status TEXT NOT NULL CHECK(status IN('pending','complete','failed')),error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(conversation_id,seq));
CREATE UNIQUE INDEX one_pending_turn ON turns(conversation_id) WHERE status='pending';
CREATE TABLE completions(conversation_id TEXT NOT NULL REFERENCES conversations(id),task_id TEXT NOT NULL REFERENCES tasks(id),completed_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(conversation_id,task_id));
CREATE TABLE findings(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),turn_id TEXT NOT NULL REFERENCES turns(id),author TEXT NOT NULL REFERENCES users(email),category TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('low','moderate','high','urgent')),explanation TEXT NOT NULL,expected TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reviews(finding_id TEXT PRIMARY KEY REFERENCES findings(id),reviewer TEXT NOT NULL REFERENCES users(email),verdict TEXT NOT NULL CHECK(verdict IN('confirmed','not_confirmed','needs_more_evidence')),feedback TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX membership_email ON memberships(email,campaign_id);
CREATE INDEX scenario_campaign ON scenarios(campaign_id);
CREATE INDEX task_scenario ON tasks(scenario_id);
CREATE INDEX model_campaign ON models(campaign_id);
CREATE INDEX conversation_campaign_owner ON conversations(campaign_id,owner);
CREATE INDEX finding_conversation ON findings(conversation_id);
